package catalog

import (
	"context"
	"math"
	"regexp"

	"sodapop/ent"
	"sodapop/ent/drink"
	"sodapop/ent/drinkflavour"
)

// publicSlugPattern keeps malformed slugs from reaching the database. Only
// lower-case catalog slugs generated by Slugify are accepted.
var publicSlugPattern = regexp.MustCompile(`^[a-z0-9]+(?:-[a-z0-9]+)*$`)

// PublicBrand is the brand block exposed by the public catalog API.
type PublicBrand struct {
	Name string `json:"name"`
	Slug string `json:"slug"`
}

// PublicStyle is the style block exposed by the public catalog API.
type PublicStyle struct {
	Name string `json:"name"`
	Slug string `json:"slug"`
}

// PublicFlavour carries a flavour name and its 0-5 intensity.
type PublicFlavour struct {
	Name      string `json:"name"`
	Intensity int    `json:"intensity"`
}

// PublicRating is the 0-5 average plus the number of raters. It is omitted from
// the payload entirely until at least MinRaters people have rated the drink.
type PublicRating struct {
	Average    float64 `json:"average"`
	RaterCount int     `json:"rater_count"`
}

// PublicDrink is the deliberately narrow catalog fact sheet served without
// authentication. It never carries internal IDs, barcodes, aliases, media IDs,
// source attribution or user data.
type PublicDrink struct {
	Slug                 string          `json:"slug"`
	Name                 string          `json:"name"`
	Description          string          `json:"description"`
	Brand                *PublicBrand    `json:"brand"`
	Style                *PublicStyle    `json:"style"`
	Container            string          `json:"container"`
	VolumeML             int             `json:"volume_ml"`
	CaffeineMgPer100ml   int             `json:"caffeine_mg_per_100ml"`
	SugarGPer100ml       float64         `json:"sugar_g_per_100ml"`
	CaloriesKcalPer100ml int             `json:"calories_kcal_per_100ml"`
	Sweetener            string          `json:"sweetener"`
	Carbonation          string          `json:"carbonation"`
	Acid                 string          `json:"acid"`
	Status               string          `json:"status"`
	ImageURL             *string         `json:"image_url"`
	Flavours             []PublicFlavour `json:"flavours"`
	Rating               *PublicRating   `json:"rating"`
}

// PublicBySlug returns one published, non-merged drink with a public-safe
// status. Everything else returns ErrNotFound so callers cannot distinguish an
// unpublished row from a missing one.
func (s *Service) PublicBySlug(ctx context.Context, slug string) (*PublicDrink, error) {
	if len(slug) == 0 || len(slug) > 120 || !publicSlugPattern.MatchString(slug) {
		return nil, ErrNotFound
	}
	d, err := s.Client.Drink.Query().
		Where(
			drink.Slug(slug),
			drink.Published(true),
			drink.MergedIntoIDIsNil(),
			drink.StatusIn(drink.StatusActive, drink.StatusLimited, drink.StatusSeasonal),
		).
		WithBrand().
		WithStyle().
		Only(ctx)
	if err != nil {
		if ent.IsNotFound(err) {
			return nil, ErrNotFound
		}
		return nil, err
	}

	out := &PublicDrink{
		Slug:                 d.Slug,
		Name:                 d.Name,
		Description:          d.Description,
		Container:            string(d.Container),
		VolumeML:             d.VolumeMl,
		CaffeineMgPer100ml:   d.CaffeineMgPer100ml,
		SugarGPer100ml:       d.SugarGPer100ml,
		CaloriesKcalPer100ml: d.CaloriesKcalPer100ml,
		Sweetener:            string(d.Sweetener),
		Carbonation:          string(d.Carbonation),
		Acid:                 string(d.Acid),
		Status:               string(d.Status),
		ImageURL:             d.ImageURL,
		Flavours:             []PublicFlavour{},
	}
	if b := d.Edges.Brand; b != nil {
		out.Brand = &PublicBrand{Name: b.Name, Slug: b.Slug}
	}
	if st := d.Edges.Style; st != nil {
		out.Style = &PublicStyle{Name: st.Name, Slug: st.Slug}
	}

	rows, err := s.Client.DrinkFlavour.Query().
		Where(drinkflavour.DrinkID(d.ID)).
		WithFlavour().
		Order(ent.Asc(drinkflavour.FieldFlavourID)).
		All(ctx)
	if err != nil {
		return nil, err
	}
	for _, f := range rows {
		if f.Edges.Flavour != nil {
			out.Flavours = append(out.Flavours, PublicFlavour{
				Name:      f.Edges.Flavour.Name,
				Intensity: f.Intensity,
			})
		}
	}

	r := s.rating(ctx, d.ID)
	if r.Shown && r.Avg != nil {
		out.Rating = &PublicRating{
			Average:    math.Round((*r.Avg/4.0)*100) / 100,
			RaterCount: r.RaterCount,
		}
	}
	return out, nil
}
